create or replace function public.onboard_organization(business_name text,business_slug text,owner_name text) returns uuid language plpgsql security definer set search_path=public as $$ declare new_org uuid; starter_plan uuid; begin if auth.uid() is null then raise exception 'Debes iniciar sesión'; end if; if exists(select 1 from public.profiles where id=auth.uid()) then raise exception 'La cuenta ya pertenece a un negocio'; end if; business_name:=trim(business_name);business_slug:=lower(trim(business_slug));owner_name:=trim(owner_name);if length(business_name)<3 then raise exception 'El nombre del negocio es demasiado corto';end if;if business_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then raise exception 'El identificador solo admite letras, números y guiones';end if;select id into starter_plan from public.plans where code='starter' and active=true;if starter_plan is null then raise exception 'No existe un plan inicial activo';end if;insert into public.organizations(name,slug) values(business_name,business_slug) returning id into new_org;insert into public.profiles(id,organization_id,full_name,role,active) values(auth.uid(),new_org,nullif(owner_name,''),'owner',true);insert into public.business_settings(organization_id,business_name) values(new_org,business_name);insert into public.organization_subscriptions(organization_id,plan_id,status,trial_ends_at,current_period_ends_at) values(new_org,starter_plan,'trialing',now()+interval '14 days',now()+interval '14 days');return new_org;exception when unique_violation then raise exception 'Ese identificador de negocio ya está en uso';end $$;
revoke all on function public.onboard_organization(text,text,text) from public;grant execute on function public.onboard_organization(text,text,text) to authenticated;

